mapper.select:
SELECT COUNT(*)
FROM DRAMA
WHERE YEAR(released_at) = #{year}

	SELECT 
		drama_id AS dramaId,
        title AS title,
        released_at AS releasedAt,
        description AS description
	FROM DRAMA
	WHERE YEAR(released_at) = #{year}
	ORDER BY released_at DESC, drama_id DESC
    LIMIT #{size}
    OFFSET #{offset}

SELECT dg.drama_id as dramaId, g.genre_id as genreId, g.name as name FROM DramaGenre dg join Genre g on dg.genre_id = g.genre_id WHERE dg.drama_id IN
#{dramaId}
ORDER BY dg.drama_id ASC, g.name ASC

SELECT genre_id as genreId, name
FROM Genre
WHERE genre_id = #{genreId}

SELECT COUNT(*)
FROM DramaGenre
WHERE genre_id = #{genreId}

SELECT EXISTS (
	SELECT 1
	FROM Drama
	WHERE drama_id = #{dramaId}
)

SELECT drama_id AS dramaId, img_id AS imgId, url AS url FROM DramaImg WHERE drama_id IN
#{dramaId}
ORDER BY drama_id ASC, img_id ASC
